# Break My Fix finding 1, generated by Tracefix: _aggregate_period raises UnboundLocalError.
# Property (issue): Aggregating any list of snapshots, including ones whose error counters are unsupported (None or missing), returns a summary and never raises.
# Quote: using comparison API data with unsupported/null DOCSIS error counters
# Run it with pytest: it fails for as long as the code breaks this property.

from comparison.routes import _aggregate_period


def test_break_my_fix_1() -> None:
    snapshots = [{'timestamp': '2024-01-01T00:00:00Z', 'summary': {'ds_power_avg': 1.0, 'ds_snr_avg': 40.0, 'us_power_avg': 45.0, 'ds_correctable_errors': None, 'ds_uncorrectable_errors': None, 'health': 'good'}}]
    result = _aggregate_period(snapshots=[{'timestamp': '2024-01-01T00:00:00Z', 'summary': {'ds_power_avg': 1.0, 'ds_snr_avg': 40.0, 'us_power_avg': 45.0, 'ds_correctable_errors': None, 'ds_uncorrectable_errors': None, 'health': 'good'}}])
    assert (isinstance(result, dict))
